<?php
namespace App\Services; use App\Core\Application;
final class UploadService{public function __construct(private Application $app){} public function validate(array $f):array{$ext=strtolower(pathinfo($f['name']??'',PATHINFO_EXTENSION));$cfg=$this->app->config()->get('uploads'); if(($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)return [false,'Yükleme hatası.']; if(($f['size']??0)>$cfg['max_size'])return [false,'Dosya çok büyük.']; if(!in_array($ext,$cfg['allowed_extensions'],true))return [false,'Dosya türü yasak.']; $mime=(new \finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']); if(!in_array($mime,$cfg['allowed_mimes'],true))return [false,'MIME türü geçersiz.']; if($ext==='svg'){ $svg=file_get_contents($f['tmp_name']); if(preg_match('/<script|on\w+=|foreignObject|iframe|https?:\/\//i',$svg))return [false,'SVG güvenlik kontrolünden geçmedi.']; } elseif(!getimagesize($f['tmp_name'])) return [false,'Geçerli görsel değil.']; return [true,''];}}
